import java.util.Scanner;

public class Main {

	public void solve() {
		Scanner sc = new Scanner(System.in);
		long W = sc.nextLong();
		long M = sc.nextLong();
		int cur = 0;
		while (Math.pow(W, cur) < M) {
			cur++;
		}
		if (Math.pow(W, cur) == M) {
			System.out.println("YES");
			return;
		}

		long MAX = (long) Math.pow(W, cur);
		long sum = (MAX - 1) / (W - 1);
		if (MAX - sum == M) {
			System.out.println("YES");
			return;
		}
		if (dfs(W, M)) {
			System.out.println("YES");
		} else {
			System.out.println("NO");
		}

	}

	private boolean dfs(long W, long M) {
		if (M == 1) {
			return true;
		}
		if (M % W == 0) {
			return dfs(W, M / W);
		} else if ((M - 1) % W == 0) {
			return dfs(W, (M - 1) / W);
		} else if ((M + 1) % W == 0) {
			return dfs(W, (M + 1) / W);
		}
		return false;
	}

	public static void main(String[] args) {
		new Main().solve();
	}

}
